/**
 * Generate Boolean Telemetry Records - Compact Payload
 * 
 * INPUT:
 *   $ (payload): Single batch from broadcast
 *   {
 *     batchData: {
 *       type: 1,
 *       windowStart: "2026-01-13T15:00:00.000Z",
 *       windowEnd: "2026-01-13T15:05:00.000Z",
 *       frequency: 5000,
 *       batchIndex: 1,
 *       count: 2,
 *       timezone: "America/Detroit",
 *       anomalyEnabled: true,
 *       anomalyProb: 0.02
 *     },
 *     dataPoints: [
 *       { id: "DP-100", props: "ASSET-001.Running" },
 *       { id: "DP-101", props: "ASSET-001.FaultActive" }
 *     ]
 *   }
 * 
 * PROPS FORMAT: "name" (for pattern matching)
 * 
 * OUTPUT:
 *   [{ create: { dataPointId, recordedAt, valueBool? } }, ...]
 */

'use strict';

// Extract batch properties
var batch = $ || {};
var batchData = batch.batchData || {};
var dataPoints = batch.dataPoints || [];

var frequency = batchData.frequency || 5000;
var windowStartMs = new Date(batchData.windowStart).getTime();
var windowEndMs = new Date(batchData.windowEnd).getTime();
var anomalyEnabled = batchData.anomalyEnabled !== false;
var anomalyProb = batchData.anomalyProb || 0.02;

// Validate window
if (isNaN(windowStartMs) || isNaN(windowEndMs)) {
  console.error('ERROR: Invalid window timestamps');
  return [];
}

// ============================================================
// BOOLEAN VALUE GENERATOR
// ============================================================

function generateBooleanValue(name, timestamp, prevValue) {
  var nameLower = (name || '').toLowerCase();
  var hour = new Date(timestamp).getUTCHours();
  var isWorkHours = hour >= 6 && hour <= 22;
  
  var value;
  var changeProb = 0.05;
  
  // --------------------------------------------------------
  // RUNNING / ACTIVE / ENABLED - High during work hours
  // --------------------------------------------------------
  if (nameLower.indexOf('running') >= 0 || nameLower.indexOf('active') >= 0 || 
      nameLower.indexOf('enabled') >= 0 || nameLower.indexOf('online') >= 0 ||
      nameLower.indexOf('inservice') >= 0) {
    
    if (prevValue === null || prevValue === undefined) {
      value = isWorkHours && Math.random() < 0.9;
    } else {
      if (isWorkHours) {
        changeProb = prevValue ? 0.02 : 0.15;
      } else {
        changeProb = prevValue ? 0.1 : 0.02;
      }
      value = Math.random() < changeProb ? !prevValue : prevValue;
    }
  }
  
  // --------------------------------------------------------
  // FAULT / ALARM / ERROR - Rare, but sticky when triggered
  // --------------------------------------------------------
  else if (nameLower.indexOf('fault') >= 0 || nameLower.indexOf('alarm') >= 0 || 
           nameLower.indexOf('error') >= 0 || nameLower.indexOf('fail') >= 0 ||
           nameLower.indexOf('trip') >= 0) {
    
    if (prevValue === null || prevValue === undefined) {
      value = Math.random() < 0.02;
    } else if (prevValue) {
      value = Math.random() < 0.1 ? false : true;
    } else {
      var faultProb = anomalyEnabled ? anomalyProb : 0.01;
      value = Math.random() < faultProb;
    }
  }
  
  // --------------------------------------------------------
  // SAFETY / READY / OK / HEALTHY - Usually true
  // --------------------------------------------------------
  else if (nameLower.indexOf('safety') >= 0 || nameLower.indexOf('ready') >= 0 || 
           nameLower.indexOf('ok') >= 0 || nameLower.indexOf('healthy') >= 0 ||
           nameLower.indexOf('normal') >= 0 || nameLower.indexOf('good') >= 0) {
    
    if (prevValue === null || prevValue === undefined) {
      value = Math.random() < 0.95;
    } else {
      changeProb = prevValue ? 0.01 : 0.2;
      value = Math.random() < changeProb ? !prevValue : prevValue;
    }
  }
  
  // --------------------------------------------------------
  // OPEN / CLOSED - Binary state, changes occasionally
  // --------------------------------------------------------
  else if (nameLower.indexOf('open') >= 0 || nameLower.indexOf('closed') >= 0 ||
           nameLower.indexOf('valve') >= 0 || nameLower.indexOf('door') >= 0 ||
           nameLower.indexOf('gate') >= 0) {
    
    if (prevValue === null || prevValue === undefined) {
      value = Math.random() < 0.5;
    } else {
      changeProb = 0.03;
      value = Math.random() < changeProb ? !prevValue : prevValue;
    }
  }
  
  // --------------------------------------------------------
  // ON / OFF - Similar to running
  // --------------------------------------------------------
  else if (nameLower.indexOf('.on') >= 0 || nameLower.indexOf('_on') >= 0 ||
           nameLower.indexOf('.off') >= 0 || nameLower.indexOf('_off') >= 0 ||
           nameLower.indexOf('ison') >= 0) {
    
    if (prevValue === null || prevValue === undefined) {
      value = isWorkHours && Math.random() < 0.7;
    } else {
      changeProb = 0.05;
      value = Math.random() < changeProb ? !prevValue : prevValue;
    }
  }
  
  // --------------------------------------------------------
  // LIMIT / HIGH / LOW - Rare triggers
  // --------------------------------------------------------
  else if (nameLower.indexOf('limit') >= 0 || nameLower.indexOf('high') >= 0 || 
           nameLower.indexOf('low') >= 0 || nameLower.indexOf('max') >= 0 ||
           nameLower.indexOf('min') >= 0) {
    
    if (prevValue === null || prevValue === undefined) {
      value = Math.random() < 0.05;
    } else {
      changeProb = prevValue ? 0.15 : 0.02;
      value = Math.random() < changeProb ? !prevValue : prevValue;
    }
  }
  
  // --------------------------------------------------------
  // AUTO / MANUAL - Mode switches, infrequent changes
  // --------------------------------------------------------
  else if (nameLower.indexOf('auto') >= 0 || nameLower.indexOf('manual') >= 0 ||
           nameLower.indexOf('mode') >= 0) {
    
    if (prevValue === null || prevValue === undefined) {
      value = Math.random() < 0.8;
    } else {
      changeProb = 0.01;
      value = Math.random() < changeProb ? !prevValue : prevValue;
    }
  }
  
  // --------------------------------------------------------
  // COMPLETE / DONE / FINISHED - Cycle-based
  // --------------------------------------------------------
  else if (nameLower.indexOf('complete') >= 0 || nameLower.indexOf('done') >= 0 ||
           nameLower.indexOf('finished') >= 0 || nameLower.indexOf('cycle') >= 0) {
    
    if (prevValue === null || prevValue === undefined) {
      value = false;
    } else if (prevValue) {
      value = false;
    } else {
      value = isWorkHours && Math.random() < 0.1;
    }
  }
  
  // --------------------------------------------------------
  // DEFAULT - Random with some persistence
  // --------------------------------------------------------
  else {
    if (prevValue === null || prevValue === undefined) {
      value = Math.random() < 0.5;
    } else {
      changeProb = 0.05;
      value = Math.random() < changeProb ? !prevValue : prevValue;
    }
  }
  
  // --------------------------------------------------------
  // ANOMALY INJECTION
  // --------------------------------------------------------
  if (anomalyEnabled && Math.random() < anomalyProb * 0.5) {
    value = !value;
  }
  
  return value;
}

// ============================================================
// MAIN RECORD GENERATION
// ============================================================

var records = [];

for (var d = 0; d < dataPoints.length; d++) {
  var dp = dataPoints[d];
  var dpId = dp.id;
  var name = dp.props || '';
  
  var ts = windowStartMs;
  var prevValue = null;
  
  while (ts < windowEndMs) {
    var value = generateBooleanValue(name, ts, prevValue);
    
    var record = {
      create: {
        dataPointId: dpId,
        recordedAt: new Date(ts).toISOString()
      }
    };
    
    // Only include valueBool when true (false is default in Fuuz)
    if (value === true) {
      record.create.valueBool = true;
    }
    
    records.push(record);
    
    prevValue = value;
    ts += frequency;
  }
}

console.log('Generated ' + records.length + ' boolean records');
console.log('  DataPoints: ' + dataPoints.length);
console.log('  Frequency: ' + frequency + 'ms');
console.log('  Window: ' + batchData.windowStart + ' to ' + batchData.windowEnd);

return records;

